#include <iostream>
#include <vector>
using namespace std;

int biggest(vector<int> v) {
    int best = v[0];
    for (int x : v) {
        if (x > best) {
            best = x;
        }
    }
    return best;
}

int main() {
    vector<int> marks = {67, 92, 85};
    cout << biggest(marks) << endl;
    return 0;
}

